const String _hostsInstalledPi5 = r'''
{
  config,
  lib,
  pkgs,
  nixos-raspberrypi,
  ...
}: {
  imports = [
    # Pi 5 vendor kernel + matched firmware. Comes from
    # `nvmd/nixos-raspberrypi`; the per-Pi attribute set is
    # documented at github.com/nvmd/nixos-raspberrypi. The
    # vendor kernel is configured for 16K pages at build time
    # (CONFIG_ARM64_16K_PAGES) — that's not something `.base` is
    # opting into, it's just what the hardware-friendly Pi 5
    # kernel ships with.
    nixos-raspberrypi.nixosModules.raspberry-pi-5.base
    # Optional-but-required-in-practice: rebuilds `pkgs.jemalloc`
    # with `--with-lg-page=14` (16K-aware). Without it, any C
    # binary on cache.nixos.org that links the system jemalloc
    # aborts with "Unsupported system page size" at startup
    # because cache.nixos.org's substitutes are built for 4K
    # alignment. See nvmd/nixos-raspberrypi#64.
    nixos-raspberrypi.nixosModules.raspberry-pi-5.page-size-16k
    # All the NixBlitz feature toggles, hostname, services, etc.
    # x86 and Pi 5 only differ in bootloader / kernel / firmware;
    # everything from `installed.nix` upward is platform-agnostic.
    ./installed.nix
  ];

  # Migrate off the legacy `kernelboot` default — the new
  # generational `kernel` bootloader supports rollback to a prior
  # generation via the boot menu, matching the experience x86
  # operators already have via systemd-boot.
  boot.loader.raspberry-pi.bootloader = "kernel";

  # Enable the Pi 5's onboard 4-pin fan header. Without this dtparam
  # the `cooling_fan` device tree node stays at its default
  # `status = "disabled"` and the kernel never enrolls the fan as
  # a thermal cooling device — `/sys/class/thermal/cooling_device*`
  # comes up empty, no PWM control reaches the fan, and the SoC
  # cooks under sustained load (kernel compile, etc). The vendor
  # `nixos-raspberrypi` flake doesn't turn this on by default.
  hardware.raspberry-pi.config.all.base-dt-params.cooling_fan = {
    enable = true;
    value = "on";
  };

  # 8 GB swapfile. The Pi 5 ships with 8 GB RAM, which is enough
  # for nix-bitcoin runtime but NOT enough to compile Rust workspaces
  # like `uv` from source — rustc + LLVM linker peak around 1-1.5 GB
  # per concurrent rustc, cargo schedules multiple within a single
  # build, and OOM-kills the whole `nixos-rebuild` (taking SSH and
  # the entire system with it) midway through the closure. A swapfile
  # absorbs the spike at the cost of some I/O. Future Pi-local
  # rebuilds that miss the cachix substituters (e.g. when the
  # nixpkgs pin moves past what nvmd's CI has built) need this to
  # finish at all.
  swapDevices = [
    {
      device = "/var/lib/swapfile";
      size = 8 * 1024;
    }
  ];

  # Cap nix-daemon CPU usage so a Pi-local rebuild doesn't peg all
  # 4 cores and starve bitcoind / lnd / the dashboard tile pollers.
  # Default `max-jobs = "auto"` (=4 here) + default `cores = 0`
  # (=all available) means one rustc storm can drive load average
  # above 8 and slow `tailscale status` polls into timeouts. The
  # split below leaves the 4th core for everything else:
  #
  #   max-jobs = 1  — only one derivation at a time
  #   cores    = 3  — that derivation can spin up to 3 rustc threads
  #
  # Builds take longer in absolute terms, but the node stays
  # responsive throughout — preferable for a single-board node
  # that's also serving a live Bitcoin + Lightning stack.
  nix.settings = {
    max-jobs = 1;
    cores = 3;
  };
}
''';

const String _hostsInstalled = r'''
{
  config,
  lib,
  pkgs,
  ...
}: let
  cfg = builtins.fromJSON (builtins.readFile ../config.json);
  sys = cfg.system;
  # Bootstrap gate: during initial install, `initialized` is false and all
  # services are forced off so disko-install builds a minimal system that
  # fits in the live ISO's tmpfs. After first-boot setup, `initialized`
  # flips to true and the real service configuration is built on the
  # installed system's disk (plenty of space).
  initialized = cfg.initialized or false;

  # Generic helpers for the v18 app_configs shape.
  # `apps` is the map of app-name → config-map from config.json.
  apps = cfg.app_configs or {};

  # Read a single option from apps.<name>.<key>, falling back to `default`
  # when the app entry or the key is absent.
  appOpt = name: key: default: let
    m = apps.${name} or {};
  in
    m.${key} or default;

  # An app is active only when the system has been initialized AND the app's
  # own `enabled` flag is true.
  appEnabled = name: initialized && (appOpt name "enabled" false);
in {
  imports = [
    ../hardware-configuration.nix
  ];

  # Feed the appConfigs option declared in
  # modules/system/nixblitz-options.nix (auto-imported via
  # findModules). Plugins read this as
  # `config.nixblitz.appConfigs.<id>.<key>` for cross-app state
  # (e.g. blitz-api gating on lnd.enabled).
  nixblitz.appConfigs = apps;
  # Feed the system option declared in
  # modules/system/nixblitz-options.nix. Plugins read node-wide
  # settings as `config.nixblitz.system.<key> or default`
  # (e.g. `config.nixblitz.system.tor or true` to route over Tor).
  nixblitz.system = sys;

  networking.hostName = sys.hostname;
  time.timeZone = sys.timezone;

  features.system.base.enable = true;
  # Operator's choice of login shell. Older configs (pre-v16) don't
  # have the field — fall back to bash, the new default.
  features.system.base.shell = sys.shell or "bash";

  # Two background timers (daily light + weekly heavy) populate
  # ~/.local/state/nixblitz/update-status.json so the dashboard can
  # surface "X updates available" without the user kicking off a
  # rebuild. See templates/modules/system/update-check.nix.
  features.system.updateCheck.enable = initialized;

  # Disk layout — enable the appropriate disko config for the platform.
  # `disk_device` carries the operator's choice from the install wizard
  # forward to subsequent rebuilds; without it, post-install rebuilds
  # default the disko `device` to `/dev/vda` and grub-install fails on
  # bare metal where the disk is `/dev/sda`. Empty string falls back to
  # the disko module's per-platform default for VMs that pre-date the
  # field.
  features.system.disko-x86.enable = sys.platform == "vm" || sys.platform == "x86";
  features.system.disko-x86.device =
    if (sys.disk_device or "") != ""
    then sys.disk_device
    else "/dev/vda";
  features.system.disko-pi5.enable = sys.platform == "pi5";

  # Test-LND: secondary regtest-only LND instance for opening channels
  # against the primary node and dry-running payments via `lncli-test`.
  # Auto-enabled whenever bitcoind is on regtest; off on any real network.
  features.system.testLnd.enable =
    (appEnabled "bitcoind")
    && (appOpt "bitcoind" "network" "mainnet") == "regtest"
    && (appEnabled "lnd");

  users.users.admin = {
    isNormalUser = true;
    extraGroups = ["wheel"];
    initialPassword = "nixblitz";
  };

  # NixOS default: wheelNeedsPassword = true. The TUI authenticates
  # sudo via the SudoSession service (sudo -S -v + ~10 min keepalive),
  # so all privileged flows still work non-interactively after one
  # password prompt per session of activity.
  services.openssh.enable = true;

  system.stateVersion = "25.11";
}
''';

