const String _modulesSystemBase = r'''
{
  config,
  lib,
  pkgs,
  nixblitz,
  ...
}: let
  cfg = config.features.system.base;
in {
  options.features.system.base = {
    enable = lib.mkEnableOption "base NixBlitz system configuration";

    # The TUI surfaces this as a select in Configure → system. Both
    # candidates ship in environment.systemPackages below so flipping
    # the choice doesn't trigger a fresh closure download.
    shell = lib.mkOption {
      type = lib.types.enum ["bash" "nushell"];
      default = "bash";
      description = "Default login shell for the admin user.";
    };
  };

  config = lib.mkIf cfg.enable {
    nix.settings = {
      experimental-features = ["nix-command" "flakes"];
      trusted-users = ["root" "admin"];

      # NixBlitz's binary cache. Layered with `extra-` so the
      # operator's existing substituters (cache.nixos.org from
      # nixpkgs defaults, nixos-raspberrypi.cachix.org from the Pi
      # 5 vendor flake) stay intact.
      #
      # Baked into system nix.conf rather than relying solely on
      # `templates/flake.nix`'s `nixConfig.extra-substituters`,
      # because flake-level config is silently ignored when
      # `accept-flake-config = false` (the upstream default) — even
      # for trusted users on some nix builds. System-level
      # substituters work uniformly across every nix invocation:
      # nixos-rebuild, plain `nix build`, `nix-store --realise`,
      # and post-install nix-daemon work during plugin installs.
      #
      # If you ever want to opt OUT (e.g. run nixblitz against your
      # own private cache), `nix.settings.extra-substituters =
      # lib.mkForce [...];` in your host config wins.
      extra-substituters = ["https://attic.f44.fyi/nixblitz"];
      extra-trusted-public-keys = [
        "nixblitz:u7XgfZdWeXp1ilOIlzKzQbxWZZg9r2rVU0VBaffHtbw="
      ];
    };

    environment.systemPackages = with pkgs; [
      git
      jujutsu
      htop
      btop
      tree
      jq
      bat
      fd
      ripgrep
      neovim
      yazi
      systemctl-tui
      # Used by the TUI's Update view to render a per-package
      # version diff (`[U.] bitcoind 27.1, 27.2`) between the
      # running system and the dry-built next generation. Tiny
      # closure; also useful at the shell.
      nvd
      # sbomnix generates the CycloneDX SBOM (`sbom.cdx.json`) the TUI commits
      # after every successful rebuild — the node's package-version changelog.
      # It is baked in (rather than fetched via `nix run`) ON PURPOSE: an SBOM
      # failure now *blocks* the Apply commit (strict commit-on-success), so the
      # tool must be reliably present, including offline. CLOSURE-SIZE TRADE: it
      # pulls in sbomnix + its Python deps (~tens of MB on disk). That cost is
      # accepted for the reliability of a commit-blocking dependency; if it ever
      # becomes a problem, the alternatives are (a) make the SBOM best-effort
      # again and revert to `nix run nixpkgs#sbomnix`, or (b) gate it behind an
      # opt-in option. See docs/superpowers/specs/2026-06-28-sbom-version-tracking-design.md.
      sbomnix
      # Both shells are kept available regardless of the
      # `defaultUserShell` choice — operators flipping the option
      # via Configure shouldn't have to wait on a new closure
      # fetch, and a `nu` / `bash` invocation from a script keeps
      # working.
      bashInteractive
      nushell
      # ghostty terminfo for operators SSHing from a ghostty host —
      # without it, TERM=xterm-ghostty triggers "unknown terminal"
      # warnings from ncurses-using tools (htop, nvim, less). Tiny
      # closure; safe to ship as a default. Should move into the
      # operator-declared `extra_packages` list once #39 lands.
      ghostty.terminfo
      nixblitz.packages.${pkgs.system}.nixblitz-unwrapped
    ];

    users.defaultUserShell =
      if cfg.shell == "nushell"
      then pkgs.nushell
      else pkgs.bashInteractive;

    # Auto-launch the NixBlitz TUI on the first interactive login of
    # a session. Two snippets — one for each supported shell — both
    # installed unconditionally so a Configure → system → shell flip
    # works on the next login without re-activating the system. Only
    # the active shell sources its file.
    #
    # `NIXBLITZ_AUTOLAUNCHED` prevents recursion: nixblitz spawns
    # subshells (e.g. password change runs `chpasswd`) that would
    # otherwise re-trigger the auto-launch from inside themselves.
    # The bash variant additionally guards on `-t 0` / `-t 1` so
    # non-TTY contexts (`ssh admin@host nixos-rebuild switch`, cron,
    # build scripts) don't drop into the TUI. nushell's login.nu
    # only fires on login shells so the SSH-with-command path skips
    # naturally there.
    environment.etc."nixblitz/auto-launch.sh".text = ''
      if [ -z "''${NIXBLITZ_AUTOLAUNCHED:-}" ] && [ -t 0 ] && [ -t 1 ] \
          && command -v nixblitz >/dev/null 2>&1; then
        export NIXBLITZ_AUTOLAUNCHED=1
        nixblitz
      fi
    '';

    environment.etc."nixblitz/auto-launch.nu".text = ''
      if ($env.NIXBLITZ_AUTOLAUNCHED? | default "") == "" {
        $env.NIXBLITZ_AUTOLAUNCHED = "1"
        if (which nixblitz | length) > 0 {
          nixblitz
        }
      }
    '';

    programs.bash.interactiveShellInit = ''
      [ -r /etc/nixblitz/auto-launch.sh ] && . /etc/nixblitz/auto-launch.sh
    '';

    # NixOS has no `programs.nushell` module, so wire nushell up by
    # symlinking the system snippet into the admin user's config dir.
    # `login.nu` is nushell's analogue to `/etc/profile` — runs once
    # at login, not on every interactive `nu` subshell. The `d` rules
    # ensure the parent dirs exist; `L+` overwrites any existing
    # symlink so re-activations stay idempotent.
    systemd.tmpfiles.rules = [
      "d /home/admin/.config 0755 admin users -"
      "d /home/admin/.config/nushell 0755 admin users -"
      "L+ /home/admin/.config/nushell/login.nu - admin users - /etc/nixblitz/auto-launch.nu"
    ];
  };
}
''';

const String _modulesSystemDiskoPi5 = r'''
{
  config,
  lib,
  ...
}: let
  cfg = config.features.system.disko-pi5;
in {
  options.features.system.disko-pi5.enable =
    lib.mkEnableOption "Pi 5 disk layout (GPT, FAT firmware + ext4 root)";

  config = lib.mkIf cfg.enable {
    # Pi 5 boot path needs a FAT partition for vendor firmware,
    # device-tree blobs, overlays, and (with the `kernel`
    # bootloader from nvmd/nixos-raspberrypi) per-generation
    # kernel images. Mount point matches the upstream module's
    # default `boot.loader.raspberry-pi.firmwarePath` so we don't
    # have to wire that through here.
    #
    # Default device targets NVMe (the supported configuration
    # via the official M.2 HAT) but `disko-install --disk main
    # <path>` overrides this at install time, so the user can
    # pick SD / USB / NVMe at the wizard step regardless.
    disko.devices.disk.main = {
      device = lib.mkDefault "/dev/nvme0n1";
      type = "disk";
      content = {
        type = "gpt";
        partitions = {
          firmware = {
            # 1 GB headroom matches the upstream installer
            # image's `sdImage.firmwareSize = 1024` so multiple
            # NixOS generations + their kernels fit alongside the
            # vendor firmware blobs.
            size = "1024M";
            type = "EF00";
            content = {
              type = "filesystem";
              format = "vfat";
              mountpoint = "/boot/firmware";
              # 0077 keeps the firmware partition root-owned —
              # nothing should be reading kernel images from
              # here at runtime.
              mountOptions = ["umask=0077"];
            };
          };
          root = {
            size = "100%";
            content = {
              type = "filesystem";
              format = "ext4";
              mountpoint = "/";
            };
          };
        };
      };
    };
  };
}
''';

const String _modulesSystemDiskoX86 = r'''
{
  config,
  lib,
  ...
}: let
  cfg = config.features.system.disko-x86;
in {
  options.features.system.disko-x86 = {
    enable =
      lib.mkEnableOption
      "x86 disk layout (GPT, BIOS-boot + ESP + ext4 root)";

    device = lib.mkOption {
      type = lib.types.str;
      default = "/dev/vda";
      description = ''
        Block device to install onto. Defaults to `/dev/vda`
        (the qemu virtio default, fine for VMs); overridden to
        the operator's actual install target on bare metal.
        Without an override, post-install rebuilds on bare-metal
        x86 try to install GRUB onto a non-existent /dev/vda.
        Set by `installed.nix` from `system.disk_device` in
        `config.json`, which the install wizard records before
        running disko-install.
      '';
    };
  };

  config = lib.mkIf cfg.enable {
    # Hybrid GPT layout — boots on both BIOS (qemu/Proxmox/older
    # hardware) and UEFI (essentially every modern x86 board)
    # without operator intervention. Three partitions:
    #
    # 1. `bios` (1 MB, type EF02): GRUB's BIOS-boot partition.
    #    No filesystem; GRUB embeds its core image directly into
    #    the partition bytes.
    # 2. `esp` (512 MB, type EF00, FAT32): the EFI System
    #    Partition. Mounted at /boot. Holds the GRUB EFI binary
    #    + the kernel / initrd images.
    # 3. `root` (rest, ext4): the system + /nix/store + /home.
    #
    # Without the ESP, a UEFI machine can't find an EFI binary
    # and hangs at firmware setup ("no boot device") — which is
    # exactly the regression that hit the operator's first
    # bare-metal install. Adding the ESP costs 512 MB and makes
    # the same image portable across firmware modes.
    disko.devices.disk.main = {
      device = cfg.device;
      type = "disk";
      content = {
        type = "gpt";
        partitions = {
          bios = {
            size = "1M";
            type = "EF02";
            # Must come first on the disk for GRUB's BIOS embed
            # to find it.
            priority = 1;
          };
          esp = {
            size = "512M";
            type = "EF00";
            content = {
              type = "filesystem";
              format = "vfat";
              mountpoint = "/boot";
              # Restrict the firmware partition to root — nothing
              # at runtime should be reading kernels from there.
              mountOptions = ["umask=0077"];
            };
          };
          root = {
            size = "100%";
            content = {
              type = "filesystem";
              format = "ext4";
              mountpoint = "/";
            };
          };
        };
      };
    };

    # GRUB in dual-mode: BIOS install lands on the EF02
    # partition (disko sets boot.loader.grub.devices for us),
    # EFI install lands at /EFI/BOOT/BOOTX64.EFI on the ESP.
    # `efiInstallAsRemovable = true` uses the standard fallback
    # path, so the firmware finds the binary without needing an
    # NVRAM entry — robust for VMs (no persistent NVRAM) and
    # reinstalls onto different disks.
    boot.loader.grub = {
      enable = true;
      efiSupport = true;
      efiInstallAsRemovable = true;
    };
  };
}
''';

const String _modulesSystemNixblitzOptions = r'''
{lib, ...}: {
  # Read-only view of `config.json`'s `app_configs.*` block, exposed
  # at the NixOS-config level so plugins can do cross-app reads
  # without depending on a plugin ABI extension.
  #
  # E.g. blitz-api checks `config.nixblitz.appConfigs.lnd.enabled or
  # false` to decide whether to wire LND's admin macaroon. Replaces
  # the `config.features.apps.<id>.{enable,network}` accessor that
  # came out with the bitcoind/lnd/cln plugin extraction — that
  # wiring assumed every core app had a NixOS-options frontend, but
  # extracted plugins no longer declare those options.
  #
  # Type is deliberately loose (`attrsOf attrs`) — the shape of each
  # app's block is whatever its plugin's `config_schema` declares,
  # and we don't want to repeat that schema here. Plugins read
  # individual keys with `or default` fallbacks.
  #
  # The option is FED from `templates/hosts/installed.nix`'s `apps =
  # cfg.app_configs or {}` let-binding (single source of truth — the
  # same map the helpers `appOpt` / `appEnabled` consume).
  options.nixblitz.appConfigs = lib.mkOption {
    type = lib.types.attrsOf (lib.types.attrsOf lib.types.unspecified);
    default = {};
    description = ''
      The `app_configs.*` block from `~/nixblitz/config.json`,
      exposed for cross-plugin reads. Plugins access individual
      keys via `config.nixblitz.appConfigs.<id>.<key> or default`.
    '';
  };

  options.nixblitz.system = lib.mkOption {
    type = lib.types.attrsOf lib.types.unspecified;
    default = {};
    description = ''
      Read-only view of `config.json`'s `system.*` block, exposed at
      the NixOS-config level so modules and plugins can read node-wide
      settings without a plugin ABI extension. E.g. a plugin reads
      `config.nixblitz.system.tor or true` to decide whether to route
      its traffic over Tor.
    '';
  };
}
''';

const String _modulesSystemPinFlakeSources = r'''
# Pin the flake input SOURCE trees into the system closure so the
# path-locked flake.lock written by the offline installer keeps
# resolving forever: disko-install copies these to the target, each
# generation pins the sources it was built from, GC frees old ones
# with old generations. ~600 MB — the COMPLETE offline lock graph
# (every `type = "path"` node), dominated by the three nixpkgs snapshots
# (stable + the two unstable forks, ~200 MB each). See the
# offline-installer spec §4.3.
#
# Completeness is not optional. `flakeInputs` (templates/flake.nix's
# `pinnedFlakeInputs`) must mirror the offline lock graph node-for-node:
# first-boot eval of the path-locked `~/nixblitz` forces the FULL
# transitive source set (nixblitz.packages -> root outputs ->
# flake-utils.lib.eachDefaultSystem -> flake-utils -> its `systems`
# input; nix-filter; both unstable nixpkgs; nixos-raspberrypi's
# argononed/flake-compat/nixos-images). Any node the ISO bakes but this
# pin omits is absent on the installed node and bricks first boot offline
# with `path '/nix/store/…-source' does not exist` — the `systems`
# (nix-systems/default) incident. attrValues pins whatever it's given;
# the completeness guarantee lives at the call site.
{
  lib,
  flakeInputs ? null,
  ...
}: {
  config = lib.mkIf (flakeInputs != null) {
    environment.etc."nixblitz/flake-inputs".text =
      lib.concatMapStrings (p: "${p}\n") (lib.attrValues flakeInputs);
  };
}
''';

const String _modulesSystemTestLnd = r'''
{
  config,
  lib,
  pkgs,
  ...
}: let
  cfg = config.features.system.testLnd;

  user = "lnd-test";
  group = "lnd-test";
  dataDir = "/var/lib/lnd-test";
  pwFile = "${dataDir}/.wallet-password";
  seedFile = "${dataDir}/.seed-mnemonic";
  # Sentinel we write only after lndinit init-wallet succeeds. Using a
  # marker (instead of "wallet.db exists") means a partial half-init
  # from an earlier failing config doesn't fool us into skipping the
  # real init on the next boot.
  initMarker = "${dataDir}/.wallet-initialized";
  # LND's own layout — chain/ sits directly under dataDir, NOT under a
  # data/ subdir. Matches nix-bitcoin's services.lnd.networkDir.
  networkDir = "${dataDir}/chain/bitcoin/regtest";

  # Reference the primary bitcoind the nix-bitcoin module defines.
  # We talk to it via the group-readable regtest cookie file — no need
  # to thread nix-bitcoin's secrets through for a local test node.
  bitcoind = config.services.bitcoind;
  cookiePath = "${bitcoind.dataDir}/regtest/.cookie";

  # nix-bitcoin ships the `lndinit` helper for headless wallet creation.
  # Grab it from their package set; we already import nix-bitcoin's
  # default NixOS module elsewhere in the system.
  lndinit = "${config.nix-bitcoin.pkgs.lndinit}/bin/lndinit";

  # ZMQ publisher URLs come from nix-bitcoin in tcp://0.0.0.0:PORT form
  # (or [::]); LND won't resolve those to loopback by itself, so swap
  # them to explicit localhost.
  zmqFix = builtins.replaceStrings ["0.0.0.0" "[::]"] ["127.0.0.1" "[::1]"];

  # Alt ports so we don't collide with the primary LND.
  p2pPort = 9736;
  rpcPort = 10010;
  restPort = 8081;

  configFile = pkgs.writeText "lnd-test.conf" ''
    datadir=${dataDir}
    tlscertpath=${dataDir}/tls.cert
    tlskeypath=${dataDir}/tls.key

    # journald already timestamps + tags; no need to log to file.
    logging.file.disable=1
    logging.console.no-timestamps=1

    listen=127.0.0.1:${toString p2pPort}
    rpclisten=127.0.0.1:${toString rpcPort}
    restlisten=127.0.0.1:${toString restPort}

    bitcoin.regtest=1
    bitcoin.node=bitcoind

    bitcoind.rpchost=127.0.0.1:${toString bitcoind.rpc.port}
    bitcoind.rpccookie=${cookiePath}
    bitcoind.zmqpubrawblock=${zmqFix bitcoind.zmqpubrawblock}
    bitcoind.zmqpubrawtx=${zmqFix bitcoind.zmqpubrawtx}

    # The wallet is created headlessly in preStart via lndinit; LND then
    # auto-unlocks on every subsequent boot from the same password file.
    wallet-unlock-password-file=${pwFile}
  '';

  # Admin-friendly wrapper: no arguments needed to hit the right
  # rpcserver/cert/macaroon combo.
  lncliTest = pkgs.writeShellScriptBin "lncli-test" ''
    exec ${pkgs.lnd}/bin/lncli \
      -n regtest \
      --rpcserver=127.0.0.1:${toString rpcPort} \
      --tlscertpath=${dataDir}/tls.cert \
      --macaroonpath=${networkDir}/admin.macaroon \
      "$@"
  '';
in {
  options.features.system.testLnd = {
    enable =
      lib.mkEnableOption
      "secondary LND instance for regtest testing — NOT for production";
  };

  config = lib.mkIf cfg.enable {
    assertions = [
      {
        assertion = bitcoind.regtest;
        message =
          "features.system.testLnd requires bitcoind running on regtest. "
          + "Set app_configs.bitcoind.network = \"regtest\" in config.json first.";
      }
    ];

    users.users.${user} = {
      isSystemUser = true;
      group = group;
      home = dataDir;
      description = "lnd-test (regtest-only secondary LND)";
      # Need the bitcoin group to read bitcoind's regtest cookie file.
      extraGroups = [bitcoind.group];
    };
    users.groups.${group} = {};

    # Admin gets group-read access to the macaroon so `lncli-test`
    # works without sudo.
    users.users.admin.extraGroups = [group];

    systemd.services.lnd-test = {
      wantedBy = ["multi-user.target"];
      requires = ["bitcoind.service"];
      after = ["bitcoind.service"];
      description = "lnd-test (regtest-only secondary LND)";
      preStart = ''
        set -eu
        # Trace every command so the journal shows exactly what ran.
        set -x

        # Debug snapshot of state on entry.
        ${pkgs.coreutils}/bin/ls -la ${dataDir} \
          || echo "(dataDir doesn't exist yet)"

        # One-time wallet password seed; persists across reboots and
        # rebuilds so the wallet stays unlockable.
        if [ ! -s ${pwFile} ]; then
          ${pkgs.coreutils}/bin/tr -dc '[:alnum:]' < /dev/urandom \
            | ${pkgs.coreutils}/bin/head -c 64 > ${pwFile}
          chmod 600 ${pwFile}
        fi

        # Headless wallet init on first boot. LND's `wallet-unlock-password-file`
        # only *unlocks* an existing wallet — creation has to happen out
        # of band via lndinit. Use a marker file we only touch after a
        # successful init so stale wallet fragments from a previous
        # broken attempt force a clean re-init.
        if [ ! -f ${initMarker} ]; then
          echo "lnd-test: wallet not initialized, running lndinit"

          # Nuke any leftover chain state so lndinit starts from
          # scratch. Also clear the bogus `data/` subdir left behind
          # by earlier broken runs of this module.
          ${pkgs.coreutils}/bin/rm -rf \
            ${dataDir}/chain \
            ${dataDir}/data \
            ${dataDir}/graph \
            ${dataDir}/.lnd

          if [ ! -s ${seedFile} ]; then
            (umask 0077; ${lndinit} gen-seed > ${seedFile})
          fi
          ${pkgs.coreutils}/bin/mkdir -p ${networkDir}

          ${lndinit} -v init-wallet \
            --file.seed=${seedFile} \
            --file.wallet-password=${pwFile} \
            --init-file.output-wallet-dir=${networkDir}

          ${pkgs.coreutils}/bin/ls -la ${networkDir}
          ${pkgs.coreutils}/bin/touch ${initMarker}
          echo "lnd-test: wallet init complete, marker written"
        else
          echo "lnd-test: wallet already initialized (marker present)"
        fi
      '';
      serviceConfig = {
        Type = "notify";
        ExecStart = "${pkgs.lnd}/bin/lnd --configfile=${configFile}";
        # The ReadWritePaths on StateDirectory gives us the dataDir.
        StateDirectory = "lnd-test";
        StateDirectoryMode = "0750";
        User = user;
        Group = group;
        TimeoutStartSec = "15min";
        Restart = "on-failure";
        RestartSec = "10s";
        # LND generates tls.cert very early (before wallet unlock) and
        # admin.macaroon shortly after. Chgrp both to the lnd-test group
        # so the admin user (member of that group) can use lncli-test.
        # tls.cert is chmod'd as soon as it appears; macaroon chmod
        # waits for the wallet to finish unlocking.
        ExecStartPost = pkgs.writeShellScript "lnd-test-perms" ''
          cert=${dataDir}/tls.cert
          mac=${networkDir}/admin.macaroon

          # tls.cert: relax perms immediately once LND has written it.
          for _ in $(${pkgs.coreutils}/bin/seq 1 30); do
            if [ -f "$cert" ]; then
              ${pkgs.coreutils}/bin/chgrp ${group} "$cert" || true
              ${pkgs.coreutils}/bin/chmod 640 "$cert" || true
              break
            fi
            ${pkgs.coreutils}/bin/sleep 0.5
          done

          # admin.macaroon: appears after wallet unlock. Also unlock the
          # intermediate dirs so group traversal works.
          for _ in $(${pkgs.coreutils}/bin/seq 1 60); do
            if [ -f "$mac" ]; then
              ${pkgs.coreutils}/bin/chgrp ${group} "$mac" || true
              ${pkgs.coreutils}/bin/chmod 640 "$mac" || true
              ${pkgs.coreutils}/bin/chmod g+rx \
                ${dataDir}/chain \
                ${dataDir}/chain/bitcoin \
                ${networkDir} || true
              exit 0
            fi
            ${pkgs.coreutils}/bin/sleep 0.5
          done
          # Best-effort; don't fail startup if macaroon isn't there yet.
          exit 0
        '';
      };
    };

    environment.systemPackages = [lncliTest];
  };
}
''';

const String _modulesSystemUpdateCheck = r'''
{
  config,
  lib,
  pkgs,
  ...
}: let
  cfg = config.features.system.updateCheck;
  # Where the checker writes its result. The TUI dashboard banner
  # reads from this. Path mirrored in
  # `common/lib/src/models/update_status.dart` (`updateStatusPath`).
  stateDir = "/var/lib/nixblitz-tui";
in {
  options.features.system.updateCheck = {
    enable = lib.mkEnableOption ''
      Periodic upstream-update check for the dashboard banner. Runs
      `nix flake update` + `nix build --dry-run` + `nvd diff` against
      the operator's `~/nixblitz/` in a tmpdir, then stages any
      candidate `flake.lock` + plugin pin moves at
      /var/lib/nixblitz-tui/staging/ so Apply can promote them.
      Daily timer; ~125 MB tarball traffic per run.
    '';
  };

  config = lib.mkIf cfg.enable {
    # Owned by admin so the timer-driven `nixblitz check`
    # invocations (run as User=admin) can write their results here.
    # `staging/` is provisioned with the same ownership so the
    # check service can drop candidate artifacts in without sudo.
    systemd.tmpfiles.rules = [
      "d ${stateDir} 0755 admin users -"
      "d ${stateDir}/staging 0755 admin users -"
    ];

    systemd.services.nixblitz-check = {
      description = "NixBlitz: probe upstream + stage candidate updates";
      after = ["network-online.target"];
      wants = ["network-online.target"];
      serviceConfig = {
        Type = "oneshot";
        User = "admin";
        # Resolve nixblitz via the system PATH so the wrapper
        # picks up disko + git like an interactive shell would.
        ExecStart = "${pkgs.runtimeShell} -lc 'nixblitz check'";
        # The check pulls tarballs + evaluates a NixOS system —
        # 5-10 min on a Pi, ~1-2 min on x86. Cap so a stuck run
        # doesn't keep the timer locked indefinitely.
        TimeoutStartSec = "30min";
      };
    };

    systemd.timers.nixblitz-check = {
      description = "NixBlitz update check (daily)";
      wantedBy = ["timers.target"];
      timerConfig = {
        OnCalendar = "daily";
        Persistent = true;
        # Spread up to 6h so simultaneous evaluations don't all
        # land on cache.nixos.org / nixos-raspberrypi.cachix.org
        # at the same minute.
        RandomizedDelaySec = "6h";
      };
    };
  };
}
''';

Map<String, String> _getAllTemplates() {
  return {
    'flake.nix': _flake,
